namespace LovingCoolStudio;

public sealed class MainForm : Form {
 readonly PanelDevice panel=new(); readonly SensorService sensors=new(); readonly System.Windows.Forms.Timer timer=new(){Interval=500}; readonly NotifyIcon tray=new();
 readonly Color bg=Color.FromArgb(8,12,20),side=Color.FromArgb(11,17,28),surface=Color.FromArgb(15,23,38),surface2=Color.FromArgb(21,31,50),line=Color.FromArgb(38,51,76),fg=Color.FromArgb(239,244,255),muted=Color.FromArgb(137,153,181),accent=Color.FromArgb(89,80,245),cyan=Color.FromArgb(38,211,255);
 readonly PreviewCanvas preview=new(){BackColor=Color.FromArgb(6,10,17)}; readonly Label device=new(); readonly ComboBox sensorPicker=new(){DropDownStyle=ComboBoxStyle.DropDownList};
